+.page {
+  min-height: 100svh;
+  overflow-x: clip;
+  background:
+    linear-gradient(var(--thorp-line) 1px, transparent 1px),
+    linear-gradient(90deg, var(--thorp-line) 1px, transparent 1px),
+    var(--thorp-background);
+  background-size: 72px 72px, 72px 72px, auto;
+  color: var(--thorp-foreground);
+}
+
+.main {
+  width: min(100% - 40px, 720px);
+  margin: 0 auto;
+  padding: clamp(90px, 15vh, 160px) 0 80px;
+}
+
+.title {
+  margin: 0 0 18px;
+  font-size: clamp(1.9rem, 5vw, 3.2rem);
+  line-height: 1.05;
+  letter-spacing: -0.05em;
+}
+
+/* 문장 하나만 담는 자리다. 행동 버튼이 없으므로 버튼 여백을 잡지 않는다. */
+.notice p {
+  max-width: 560px;
+  margin: 0;
+  color: var(--thorp-copy);
+  font-size: clamp(0.95rem, 1.8vw, 1.05rem);
+  line-height: 1.8;
+}
+
+@media (max-width: 600px) {
+  .main {
+    width: min(100% - 28px, 720px);
+    padding-top: 72px;
+  }
+}

